html:
{%- set company = frappe.get_doc("Company", doc.company) -%}
{%- set tax_reg_no = frappe.db.get_single_value("ETA Settings", "issuer_id") -%}
<style>
	.vc-inv { font-family: "Noto Sans Arabic", "Segoe UI", Tahoma, sans-serif; font-size: 12px; color: #222; }
	.vc-inv .ar { direction: rtl; text-align: right; }
	.vc-inv .head { display: flex; justify-content: space-between; align-items: flex-start; border-bottom: 2px solid #333; padding-bottom: 8px; margin-bottom: 12px; }
	.vc-inv h1 { font-size: 18px; margin: 0; }
	.vc-inv .title { text-align: center; font-size: 16px; font-weight: 600; margin: 8px 0 12px; }
	.vc-inv .parties { display: flex; gap: 16px; margin-bottom: 12px; }
	.vc-inv .box { flex: 1; border: 1px solid #ccc; border-radius: 4px; padding: 8px; }
	.vc-inv .label { color: #666; font-size: 11px; }
	.vc-inv table.lines { width: 100%; border-collapse: collapse; margin-bottom: 12px; }
	.vc-inv table.lines th, .vc-inv table.lines td { border: 1px solid #ccc; padding: 4px 6px; }
	.vc-inv table.lines th { background: #f2f2f2; font-size: 11px; }
	.vc-inv .num { text-align: right; white-space: nowrap; }
	.vc-inv table.totals { margin-left: auto; min-width: 320px; border-collapse: collapse; }
	.vc-inv table.totals td { padding: 3px 6px; }
	.vc-inv table.totals tr.grand td { border-top: 2px solid #333; font-weight: 700; font-size: 13px; }
	.vc-inv .eta { margin-top: 16px; font-size: 10px; color: #555; border-top: 1px dashed #aaa; padding-top: 6px; }
</style>
<div class="vc-inv">
	<div class="head">
		<div>
			<h1>{{ company.company_name }}</h1>
			{% if tax_reg_no %}<div>Tax Reg. No: {{ tax_reg_no }}</div>{% endif %}
		</div>
		<div class="ar">
			<h1>{{ company.company_name }}</h1>
			{% if tax_reg_no %}<div>رقم التسجيل الضريبي: {{ tax_reg_no }}</div>{% endif %}
		</div>
	</div>

	<div class="title">
		{% if doc.is_return %}Credit Note / إشعار دائن{% else %}Tax Invoice / فاتورة ضريبية{% endif %}
	</div>

	<div class="parties">
		<div class="box">
			<div class="label">Invoice No / رقم الفاتورة</div><div>{{ doc.name }}</div>
			<div class="label">Date / التاريخ</div><div>{{ frappe.utils.formatdate(doc.posting_date, "dd-MM-yyyy") }}</div>
			{% if doc.due_date %}<div class="label">Due Date / تاريخ الاستحقاق</div><div>{{ frappe.utils.formatdate(doc.due_date, "dd-MM-yyyy") }}</div>{% endif %}
			<div class="label">Currency / العملة</div><div>{{ doc.currency }}</div>
			{% if doc.po_no %}<div class="label">Customer PO / أمر شراء العميل</div><div>{{ doc.po_no }}</div>{% endif %}
		</div>
		<div class="box">
			<div class="label">Customer / العميل</div><div><strong>{{ doc.customer_name }}</strong></div>
			{% if doc.tax_id %}<div class="label">Tax ID / الرقم الضريبي</div><div>{{ doc.tax_id }}</div>{% endif %}
			{% if doc.address_display %}<div class="label">Address / العنوان</div><div>{{ doc.address_display }}</div>{% endif %}
		</div>
	</div>

	<table class="lines">
		<thead>
			<tr>
				<th>#</th>
				<th>Item / الصنف</th>
				<th>Lot / التشغيلة</th>
				<th class="num">Qty / الكمية</th>
				<th class="num">Rate / السعر</th>
				<th class="num">Amount / القيمة</th>
			</tr>
		</thead>
		<tbody>
			{% for row in doc.items %}
			<tr>
				<td>{{ row.idx }}</td>
				<td>
					{{ row.item_name }}
					{%- set cas = frappe.db.get_value("Item", row.item_code, "cas_number") -%}
					{% if cas %}<br><span class="label">CAS {{ cas }}</span>{% endif %}
				</td>
				<td>{{ row.batch_no or "" }}</td>
				<td class="num">{{ frappe.utils.fmt_money(row.qty, precision=3) }} {{ row.uom }}</td>
				<td class="num">{{ frappe.utils.fmt_money(row.net_rate, 2) }}</td>
				<td class="num">{{ frappe.utils.fmt_money(row.net_amount, 2) }}</td>
			</tr>
			{% endfor %}
		</tbody>
	</table>

	<table class="totals">
		<tr><td>Net Total / الإجمالي قبل الضريبة</td><td class="num">{{ frappe.utils.fmt_money(doc.net_total, 2) }}</td></tr>
		{% for tax in doc.taxes %}{% if tax.tax_amount %}
		<tr><td>{{ tax.description }} / ضريبة القيمة المضافة</td><td class="num">{{ frappe.utils.fmt_money(tax.tax_amount, 2) }}</td></tr>
		{% endif %}{% endfor %}
		{% if doc.discount_amount %}<tr><td>Discount / الخصم</td><td class="num">-{{ frappe.utils.fmt_money(doc.discount_amount, 2) }}</td></tr>{% endif %}
		<tr class="grand"><td>Total / الإجمالي ({{ doc.currency }})</td><td class="num">{{ frappe.utils.fmt_money(doc.grand_total, 2) }}</td></tr>
		{% if doc.currency != "EGP" %}<tr><td>Total in EGP / الإجمالي بالجنيه</td><td class="num">{{ frappe.utils.fmt_money(doc.base_grand_total, 2) }} EGP</td></tr>{% endif %}
	</table>
	{% if doc.in_words %}<div style="margin-top:6px">{{ doc.in_words }}</div>{% endif %}

	{% if doc.eta_uuid %}
	<div class="eta">
		ETA e-invoice / الفاتورة الإلكترونية — UUID: {{ doc.eta_uuid }}{% if doc.eta_submission_uuid %} · Submission: {{ doc.eta_submission_uuid }}{% endif %}
	</div>
	{% endif %}
</div>
